import React, { useEffect, useState } from "react";
import axios from "../utils/axios";
import { useNavigate } from "react-router-dom";

const Profile = () => {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [edit, setEdit] = useState(false);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState({ text: "", type: "" });
  const navigate = useNavigate();
  const userId = localStorage.getItem("userId");

  useEffect(() => {
    setName(localStorage.getItem("name") || "");
    setEmail(localStorage.getItem("email") || "");
  }, []);

  const handleSave = async () => {
    setSaving(true);
    try {
      await axios.put(`/api/users/${userId}`, { name, email });
      localStorage.setItem("name", name);
      localStorage.setItem("email", email);
      setEdit(false);
      setMsg({ text: "Profile updated.", type: "success" });
      setTimeout(() => setMsg({ text: "", type: "" }), 3000);
    } catch {
      setMsg({ text: "Failed to update.", type: "error" });
    } finally { setSaving(false); }
  };

  const initials = name.split(" ").map(w => w[0]).join("").toUpperCase().slice(0, 2) || "?";

  return (
    <div style={{ fontFamily: "'Inter', sans-serif" }}>
      <div style={{ marginBottom: 32 }}>
        <div style={{ fontSize: 11, color: "#9b9b9b", letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 6 }}>Account</div>
        <h1 style={{ fontSize: 28, fontWeight: 700, color: "#191919", margin: 0, letterSpacing: "-0.03em" }}>Profile</h1>
      </div>

      <div style={{ maxWidth: 520 }}>
        {msg.text && (
          <div style={{ background: msg.type === "success" ? "#f0fdf4" : "#fff0f0", border: `1px solid ${msg.type === "success" ? "#bbf7d0" : "#fecaca"}`, color: msg.type === "success" ? "#15803d" : "#dc2626", borderRadius: 8, padding: "10px 14px", fontSize: 13, marginBottom: 20 }}>
            {msg.text}
          </div>
        )}

        <div style={{ background: "#fff", border: "1px solid #e8e8e6", borderRadius: 12, overflow: "hidden" }}>
          <div style={{ padding: "28px 28px 20px", borderBottom: "1px solid #e8e8e6", display: "flex", alignItems: "center", gap: 16 }}>
            <div style={{ width: 56, height: 56, borderRadius: 12, background: "#dbeafe", color: "#2563eb", fontSize: 20, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center" }}>{initials}</div>
            <div>
              <div style={{ fontSize: 17, fontWeight: 600, color: "#191919" }}>{name || "—"}</div>
              <div style={{ fontSize: 13, color: "#9b9b9b", marginTop: 2 }}>{email}</div>
            </div>
          </div>

          <div style={{ padding: "24px 28px", display: "flex", flexDirection: "column", gap: 18 }}>
            {[
              { label: "Full Name", val: name, set: setName, type: "text" },
              { label: "Email Address", val: email, set: setEmail, type: "email" },
            ].map(({ label, val, set, type }) => (
              <div key={label}>
                <label style={{ display: "block", fontSize: 13, fontWeight: 500, color: "#374151", marginBottom: 6 }}>{label}</label>
                <input type={type} value={val} disabled={!edit} onChange={e => set(e.target.value)}
                  style={{ width: "100%", padding: "9px 12px", border: "1px solid #e8e8e6", borderRadius: 8, fontSize: 14, color: edit ? "#191919" : "#6b6b6b", background: edit ? "#fff" : "#fafaf9", outline: "none", fontFamily: "'Inter', sans-serif", boxSizing: "border-box" }}
                  onFocus={e => edit && (e.target.style.borderColor = "#2563eb")}
                  onBlur={e => (e.target.style.borderColor = "#e8e8e6")} />
              </div>
            ))}

            <div style={{ display: "flex", gap: 10, paddingTop: 4 }}>
              {edit ? (
                <>
                  <button onClick={handleSave} disabled={saving} style={{ padding: "9px 20px", background: "#2563eb", color: "#fff", border: "none", borderRadius: 8, fontSize: 14, fontWeight: 500, cursor: "pointer", fontFamily: "'Inter', sans-serif" }}>
                    {saving ? "Saving…" : "Save Changes"}
                  </button>
                  <button onClick={() => setEdit(false)} style={{ padding: "9px 20px", background: "#fff", color: "#374151", border: "1px solid #e8e8e6", borderRadius: 8, fontSize: 14, cursor: "pointer", fontFamily: "'Inter', sans-serif" }}>Cancel</button>
                </>
              ) : (
                <button onClick={() => setEdit(true)} style={{ padding: "9px 20px", background: "#fafaf9", color: "#374151", border: "1px solid #e8e8e6", borderRadius: 8, fontSize: 14, cursor: "pointer", fontFamily: "'Inter', sans-serif" }}>Edit Profile</button>
              )}
            </div>
          </div>

          <div style={{ padding: "16px 28px", borderTop: "1px solid #e8e8e6", background: "#fafaf9" }}>
            <button onClick={() => { localStorage.clear(); navigate("/login"); }}
              style={{ fontSize: 13, color: "#dc2626", background: "none", border: "none", cursor: "pointer", padding: 0, fontFamily: "'Inter', sans-serif" }}>
              Sign out of Spendly
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Profile;
